window.CARDS=window.CARDS||{};CARDS["people-yamamura-miki"]=[{"i":"sc-yamamura-miki-y2v4-p5-1","v":"y2v4","y":2,"o":19,"k":"","w":"yamamura-miki","q":"yamamura miki yamamura not present page locator found zero matches for yamamura miki in year 2  vol  4  she is not on any page of this volume","h":"<article class=\"card\" id=\"sc-yamamura-miki-y2v4-p5-1\"><h3><span class=\"ttl\">Yamamura not present<\/span><span class=\"meta\">Y2V4 · p.5–284<\/span><\/h3><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Page locator found zero matches for Yamamura Miki in Year 2, Vol. 4; she is not on any page of this volume.<span class=\"pg\">p.5–284<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-yamamura-miki-y2v4_5-p95-1","v":"y2v4.5","y":2,"o":20,"k":"","w":"yamamura-miki","q":"yamamura miki sakayanagi s call  yamamura is her new watcher after kamuro is stood down and amasawa has noticed the class a tail  sakayanagi phones   could you continue for me please    the only person she can rely on from the class  yamamura san  the watch resumes through him  yamamura never appears on page in this volume  his is a phone call only  no actions or lines are attributable beyond the single exchange quoted in narration","h":"<article class=\"card\" id=\"sc-yamamura-miki-y2v4_5-p95-1\"><h3><span class=\"ttl\">Sakayanagi&#x27;s call: Yamamura is her new watcher<\/span><span class=\"meta\">Y2V4.5 · p.95<\/span><\/h3><p class=\"setup\">After Kamuro is stood down and Amasawa has noticed the Class A tail, Sakayanagi phones: &quot;Could you continue for me please?&quot; — the only person she can rely on from the class, Yamamura-san; the watch resumes through him.<\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Yamamura never appears on-page in this volume; his is a phone call only. No actions or lines are attributable beyond the single exchange quoted in narration.<span class=\"pg\">p.95<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-yamamura-miki-y2v8-p11-1","v":"y2v8","y":2,"o":24,"k":"","w":"yamamura-miki","q":"yamamura miki yamamura miki mentioned in passing named in this volume  passing mentions on pages  p 46 47  p 50  p 55 57  p 63 64  p 79  passing mention only","h":"<article class=\"card\" id=\"sc-yamamura-miki-y2v8-p11-1\"><h3><span class=\"ttl\">yamamura-miki mentioned in passing<\/span><span class=\"meta\">Y2V8 · p.11-208<\/span><\/h3><p class=\"setup\">Named in this volume.<\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Passing mentions on pages: p.46-47, p.50, p.55-57, p.63-64, p.79.<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> Passing mention only.<span class=\"pg\">p.11<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-yamamura-miki-y2v8-p46-1\">→ After: Group 6: the girl no one notices<\/button><\/div><\/article>"},{"i":"sc-yamamura-miki-y2v8-p46-1","v":"y2v8","y":2,"o":24,"k":"spoken","w":"kitou-hayato ryuuen-kakeru nishino-takeko yamamura-miki","q":"yamamura miki group 6  the girl no one notices boards with class a  on the master group list she shares group 6 with kito and the others  ayanokoji s private numbering  14  above nishino at 18  below kushida ryuen at 6  she approaches downcast  ignores kushida s greeting with a short nod  she doesn t warm to watanabe s chattiness either  watching ayanokoji fall on the beginner slope  are you okay  she slips onto the wrong  advanced  lift  following kito s back by accident or on sight   are you okay  she hovers above the ryuen group  kaneda  ishizaki  todo gathered below  she steps onto the steep slope alone and disappears down it  she lets no one see her struggle  her class a groupmate  she rides the lift after him  either by sighting or by mistake   pages keep it open  she doesn t understand why everyone treats this trip as tense  he notices her staring  she doesn t flinch when nishino engages  just keeps quiet  the  yamamura is on the move  line is untagged in the translation  kushida or ayanokoji  not assigned","h":"<article class=\"card\" id=\"sc-yamamura-miki-y2v8-p46-1\"><h3><span class=\"ttl\">Group 6: the girl no one notices<\/span><span class=\"meta\">Y2V8 · p.46–64<\/span><\/h3><p class=\"setup\">Boards with Class A; on the master group list she shares Group 6 with Kitō and the others. She approaches downcast, ignores Kushida&#x27;s greeting with a short nod; she doesn&#x27;t warm to Watanabe&#x27;s chattiness either. Watching Ayanokōji fall on the beginner slope (&quot;Are you okay?&quot;); she slips onto the wrong (advanced) lift, following Kitō&#x27;s back by accident or on sight. She hovers above the Ryūen group (Kaneda, Ishizaki, Todo gathered below); she steps onto the steep slope alone and disappears down it; she lets no one see her struggle.<\/p><p class=\"with\">with <a href=\"kitou-hayato.html\">Kitō Hayato<\/a> · <a href=\"ryuuen-kakeru.html\">Ryūen Kakeru<\/a> · <a href=\"nishino-takeko.html\">Nishino Takeko<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Are you okay?”<span class=\"pg\">p.55<\/span><\/li><\/ul><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Detail<\/span> Ayanokōji&#x27;s private numbering: 14 (above Nishino at 18, below Kushida/Ryūen at 6).<span class=\"pg\">p.47<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kitō Hayato<\/b> Her Class A groupmate; she rides the lift after him (either by sighting or by mistake — pages keep it open).<span class=\"pg\">p.46, 56<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> She doesn&#x27;t understand why everyone treats this trip as tense; he notices her staring.<span class=\"pg\">p.55–64<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nishino Takeko<\/b> She doesn&#x27;t flinch when Nishino engages, just keeps quiet.<span class=\"pg\">p.63<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The &quot;Yamamura is on the move&quot; line is untagged in the translation (Kushida or Ayanokōji); not assigned.<span class=\"pg\">p.64<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-yamamura-miki-y2v8-p11-1\">← Before: yamamura-miki mentioned in passing<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-yamamura-miki-y2v8-p78-1\">→ After: Girls&#x27; night visit: the silent attendee<\/button><\/div><\/article>"},{"i":"sc-yamamura-miki-y2v8-p78-1","v":"y2v8","y":2,"o":24,"k":"spoken","w":"watanabe-norihito amikura-mako yamamura-miki","q":"yamamura miki girls  night visit  the silent attendee she accepts the girls  visit but doesn t lean in like amikura  she sits behind watanabe  she half steps back when watanabe slides next to her   the only one bothered by proximity   no  don t worry about it  during  here we are   darkness ball  and the pillow fight she remains an observer  she passes on speaking  asked to pick ski plans   i m okay with anything    her non preference is taken as fitting in   i m okay with anything  she defaults to invisibility  minimal talk  maximum absorption of others  energy  she feels out of place even in the one room that s  hers  this week  he startles her with his sudden closeness  both keep quiet  but amikura has the social nerve to whisper  yamamura hasn t figured out what to wear to be noticed  yet","h":"<article class=\"card\" id=\"sc-yamamura-miki-y2v8-p78-1\"><h3><span class=\"ttl\">Girls&#x27; night visit: the silent attendee<\/span><span class=\"meta\">Y2V8 · p.78–89<\/span><\/h3><p class=\"setup\">She accepts the girls&#x27; visit but doesn&#x27;t lean in like Amikura; she sits behind Watanabe. She half-steps back when Watanabe slides next to her — the only one bothered by proximity. During &quot;Here we are~&quot;, &quot;Darkness ball!&quot; and the pillow fight she remains an observer; she passes on speaking. Asked to pick ski plans: &quot;I&#x27;m okay with anything.&quot; — her non-preference is taken as fitting in.<\/p><p class=\"with\">with <a href=\"watanabe-norihito.html\">Watanabe Norihito<\/a> · <a href=\"amikura-mako.html\">Amikura Mako<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“No, don&#x27;t worry about it.”<span class=\"pg\">p.81<\/span><\/li><li class=\"q spoken\">“I&#x27;m okay with anything.”<span class=\"pg\">p.88<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> She defaults to invisibility: minimal talk, maximum absorption of others&#x27; energy; she feels out of place even in the one room that&#x27;s &quot;hers&quot; this week.<span class=\"pg\">p.78–89<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Watanabe Norihito<\/b> He startles her with his sudden closeness.<span class=\"pg\">p.81<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Amikura Mako<\/b> Both keep quiet, but Amikura has the social nerve to whisper; Yamamura hasn&#x27;t figured out what to wear to be noticed (yet).<span class=\"pg\">p.78–79<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-yamamura-miki-y2v8-p46-1\">← Before: Group 6: the girl no one notices<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-yamamura-miki-y2v8-p92-1\">→ After: Day two: the silent shadow detective<\/button><\/div><\/article>"},{"i":"sc-yamamura-miki-y2v8-p92-1","v":"y2v8","y":2,"o":24,"k":"spoken","w":"ayanokouji-kiyotaka kitou-hayato ryuuen-kakeru kushida-kikyou nishino-takeko yamamura-miki","q":"yamamura miki day two  the silent shadow detective the snowman morning  she refuses to participate  she observes the builders bare handed and frozen  she tries to need nobody  she declines the shop browse  stands quietly in the cold  ryuen spots her  he pulls her arm out of the pocket to prove she has no gloves  she gives up nothing  ayanokoji offers his gloves  she takes them  she doesn t want to feel anything about this  she asks if she can pay him back  he teases out why she didn t go back to get them earlier   she has no answer that satisfies her either   no  i m  not interested   what   i don t want to   i don t want to pull them out  it s too cold   i forgot   i d feel bad giving them back to you  after i wore them  they re dirty   um  when we get to the ski resort  please let me reimburse you for the gloves   that s not what i mean  i ll get them dirty by wearing them    the kind of mood that is hard to get through  sort of   no one really  i usually spend most of my time alone   i have such a weak presence that  you probably wouldn t even notice that i m alone  it s an everyday occurrence  so i m not particularly concerned about it   i don t like myself at all  it s impossible  soup curry lunch  everyone covers yamamura s embarrassment  nobody mentions it  she sits darker than the rest  she says nothing   yamamura is  well  she s not ready yet    the beginner course report  watanabe or amikura   the translation leaves the reporter untagged  she returns to the table  quietly leaves it  kushida and nishino track her  five gifu students swarm her and nishino  yamamura apologizes for the spill   the boys ridicule her  kito shows up barking silence  his relief is silent  she survives  kushida watches the boys get dragged off by ryuen and kito  he sees her  provides her with gloves  she owes him and hates that she owes him  she apologized for bumping into a boy  the man she failed to see gets a pair of knees on throat treatment on his behalf  she barely processes it  forces the glove discovery by grabbing her arm  observes her invisibility  tries to reach her with no luck  they ride into the gifu ambush together  nishino shields her","h":"<article class=\"card\" id=\"sc-yamamura-miki-y2v8-p92-1\"><h3><span class=\"ttl\">Day two: the silent shadow detective<\/span><span class=\"meta\">Y2V8 · p.92–117<\/span><\/h3><p class=\"setup\">The snowman morning: she refuses to participate; she observes the builders bare-handed and frozen; she tries to need nobody. She declines the shop browse; stands quietly in the cold; Ryūen spots her; he pulls her arm out of the pocket to prove she has no gloves; she gives up nothing; Ayanokōji offers his gloves; she takes them; she doesn&#x27;t want to feel anything about this; she asks if she can pay him back; he teases out why she didn&#x27;t go back to get them earlier — she has no answer that satisfies her either. Soup curry lunch; everyone covers Yamamura&#x27;s embarrassment; nobody mentions it; she sits darker than the rest; she says nothing. She returns to the table; quietly leaves it; Kushida and Nishino track her; five Gifu students swarm her and Nishino; Yamamura apologizes for the spill — the boys ridicule her; Kitō shows up barking silence; his relief is silent; she survives; Kushida watches the boys get dragged off by Ryūen and Kitō.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"kitou-hayato.html\">Kitō Hayato<\/a> · <a href=\"ryuuen-kakeru.html\">Ryūen Kakeru<\/a> · <a href=\"kushida-kikyou.html\">Kushida Kikyō<\/a> · <a href=\"nishino-takeko.html\">Nishino Takeko<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“No, I&#x27;m... Not interested.”<span class=\"pg\">p.92<\/span><\/li><li class=\"q spoken\">“What...!?”<span class=\"pg\">p.98<\/span><\/li><li class=\"q spoken\">“I don&#x27;t want to.”<span class=\"pg\">p.98<\/span><\/li><\/ul><details class=\"more\"><summary>15 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “I don&#x27;t want to pull them out. It&#x27;s too cold.”<span class=\"pg\">p.98<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I forgot...”<span class=\"pg\">p.99<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I&#x27;d feel bad giving them back to you... after I wore them. They&#x27;re dirty.”<span class=\"pg\">p.100<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Um, when we get to the ski resort, please let me reimburse you for the gloves.”<span class=\"pg\">p.100<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That&#x27;s not what I mean. I&#x27;ll get them dirty by wearing them ...”<span class=\"pg\">p.100<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “The kind of mood that is hard to get through, sort of.”<span class=\"pg\">p.101<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “No one really. I usually spend most of my time alone.”<span class=\"pg\">p.101<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I have such a weak presence that... you probably wouldn&#x27;t even notice that I&#x27;m alone. It&#x27;s an everyday occurrence, so I&#x27;m not particularly concerned about it.”<span class=\"pg\">p.102<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don&#x27;t like myself at all. It&#x27;s impossible.”<span class=\"pg\">p.102<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “Yamamura is... Well, she&#x27;s not ready yet.” — the beginner-course report (Watanabe or Amikura — the translation leaves the reporter untagged).<span class=\"pg\">p.108<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> He sees her; provides her with gloves; she owes him and hates that she owes him.<span class=\"pg\">p.98–102<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kitō Hayato<\/b> She apologized for bumping into a boy; the man she failed to see gets a pair of knees-on-throat treatment on his behalf; she barely processes it.<span class=\"pg\">p.114–117<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> Forces the glove discovery by grabbing her arm.<span class=\"pg\">p.98–99<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kushida Kikyō<\/b> Observes her invisibility; tries to reach her with no luck.<span class=\"pg\">p.92–117<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nishino Takeko<\/b> They ride into the Gifu ambush together; Nishino shields her.<span class=\"pg\">p.114–117<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-yamamura-miki-y2v8-p78-1\">← Before: Girls&#x27; night visit: the silent attendee<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-yamamura-miki-y2v8-p92-2\">→ After: Passing-mention records<\/button><\/div><\/article>"},{"i":"sc-yamamura-miki-y2v8-p92-2","v":"y2v8","y":2,"o":24,"k":"","w":"yamamura-miki","q":"yamamura miki passing mention records  that sounds fun  why don t we make one with nishino san and yamamura san   amikura s snowman push   what about yamamura san    she says nothing  she declines with a tiny voice   on the other hand  there were those who continued to quietly gaze at the snowman as it was being built  it was yamamura  who had been gradually distancing herself from us without being noticed   kushida immediately accepted amikura s invitation  but yamamura refused  apparently intending on staying behind   yamamura san  aren t you going    she says   ah  i ll stay  please don t mind me   snow covered road and invaded yamamura s personal space   i don t want to    she says no firmly   i half forcefully pushed the gloves i took off to yamamura   um  when we get to the ski resort  please let me reimburse you for the gloves   the kind of mood that is hard to get through  sort of   i have such a weak presence that  you probably wouldn t even notice that i m alone  it s an everyday occurrence  so i m not particularly concerned about it   what about yamamura san   kushida  at the plan stage    wait  is that right  p 103   yamamura and i are confirmed for the beginner course    that s watanabe s line  attribution verfied earlier  the p 103 token   what about yamamura    line 17   i think it would be better if someone who can ski to follow yamamura san    kushida   cite   mentioned   p 103   i think it would be better if someone who can ski to follow yamamura san and the others   kushida   on the other hand  yamamura  whose name wasn t mentioned  had a darker expression and wasn t in high spirits   yamamura san is on her way to you   kushida s warning text   yamamura had already returned and was silently using her cellphone with a nonchalant look on her face   yamamura  who had been eating slowly here  finished her meal and took her tray to the west to match nishino   apparently  it wasn t nishino who started the trouble  but yamamura  who seemed to have bumped into the man   they made them get down on their knees in front of yamamura and nishino and beg for forgiveness   she spoke back without fear to interject between yamamura and the guys  as if she was a shield for her   nishino   i think i learned a little bit more about yamamura and kito","h":"<article class=\"card\" id=\"sc-yamamura-miki-y2v8-p92-2\"><h3><span class=\"ttl\">Passing-mention records<\/span><span class=\"meta\">Y2V8 · p.92–93, 98–103, 108–109, 113–114, 117, 143, 175<\/span><\/h3><details class=\"more\"><summary>20 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> &quot;That sounds fun. Why don&#x27;t we make one with Nishino-san and Yamamura-san?&quot; (Amikura&#x27;s snowman push)<span class=\"pg\">p.92<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> &quot;What about Yamamura-san?&quot; — she says nothing; she declines with a tiny voice.<span class=\"pg\">p.92<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> &quot;On the other hand, there were those who continued to quietly gaze at the snowman as it was being built. It was Yamamura, who had been gradually distancing herself from us without being noticed.&quot;<span class=\"pg\">p.93<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> &quot;Kushida immediately accepted Amikura&#x27;s invitation, but Yamamura refused, apparently intending on staying behind.&quot;<span class=\"pg\">p.98<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> &quot;Yamamura-san? Aren&#x27;t you going?&quot; — she says: &quot;...Ah, I&#x27;ll stay... Please don&#x27;t mind me.&quot;<span class=\"pg\">p.98<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> &quot;snow-covered road and invaded Yamamura&#x27;s personal space.&quot;<span class=\"pg\">p.99<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> &quot;I don&#x27;t want to.&quot; — she says no firmly.<span class=\"pg\">p.99<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> &quot;I half forcefully pushed the gloves I took off to Yamamura.&quot;<span class=\"pg\">p.100<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> &quot;Um, when we get to the ski resort, please let me reimburse you for the gloves.&quot;<span class=\"pg\">p.100<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> &quot;The kind of mood that is hard to get through, sort of.&quot;<span class=\"pg\">p.101<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> &quot;I have such a weak presence that... you probably wouldn&#x27;t even notice that I&#x27;m alone. It&#x27;s an everyday occurrence, so I&#x27;m not particularly concerned about it.&quot;<span class=\"pg\">p.102<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> &quot;What about Yamamura-san?&quot; (Kushida, at the plan stage) — wait, is that right? p.103: &quot;&#x27;Yamamura and I are confirmed for the beginner course&#x27;&quot; — that&#x27;s WATANABE&#x27;s line (attribution verfied earlier). The p.103 token: &quot;what about Yamamura...&quot; — line 17: &quot;I think it would be better if someone who can ski to follow Yamamura-san&quot; — kushida ✓. cite: [mentioned] (p.103) &quot;I think it would be better if someone who can ski to follow Yamamura-san and the others.&quot; (Kushida)<span class=\"pg\">p.103<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> &quot;On the other hand, Yamamura, whose name wasn&#x27;t mentioned, had a darker expression and wasn&#x27;t in high spirits.&quot;<span class=\"pg\">p.108<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> &quot;Yamamura-san is on her way to you.&quot; (Kushida&#x27;s warning text)<span class=\"pg\">p.109<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> &quot;Yamamura had already returned and was silently using her cellphone with a nonchalant look on her face.&quot;<span class=\"pg\">p.113<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> &quot;Yamamura, who had been eating slowly here, finished her meal and took her tray to the west to match Nishino.&quot;<span class=\"pg\">p.113<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> &quot;Apparently, it wasn’t Nishino who started the trouble, but Yamamura, who seemed to have bumped into the man.&quot;<span class=\"pg\">p.114<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> &quot;They made them get down on their knees in front of Yamamura and Nishino and beg for forgiveness.&quot;<span class=\"pg\">p.117<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> &quot;She spoke back without fear to interject between Yamamura and the guys, as if she was a shield for her.&quot; (Nishino)<span class=\"pg\">p.143<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> &quot;I think I learned a little bit more about Yamamura and Kitō.&quot;<span class=\"pg\">p.175<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-yamamura-miki-y2v8-p92-1\">← Before: Day two: the silent shadow detective<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-yamamura-miki-y2v8-p130-1\">→ After: The tour debate; hands in pockets<\/button><\/div><\/article>"},{"i":"sc-yamamura-miki-y2v8-p130-1","v":"y2v8","y":2,"o":24,"k":"","w":"kushida-kikyou nishino-takeko amikura-mako yamamura-miki","q":"yamamura miki the tour debate  hands in pockets she sides with the majority silently  no opinion of her own on spots  when ayanokoji s majority gambit wins  she exhales quietly  she stays a ghost through the argument  after the resolution she nods along with the sightseeing plan  her relief is invisible but real  she reads kushida s pull on the group  hangs back  they swap small talk on the bus rides  she stands near amikura during the map app stupor","h":"<article class=\"card\" id=\"sc-yamamura-miki-y2v8-p130-1\"><h3><span class=\"ttl\">The tour debate; hands in pockets<\/span><span class=\"meta\">Y2V8 · p.130–139<\/span><\/h3><p class=\"setup\">She sides with the majority silently (no opinion of her own on spots); when Ayanokōji&#x27;s majority gambit wins, she exhales quietly; she stays a ghost through the argument. After the resolution she nods along with the sightseeing plan; her relief is invisible but real.<\/p><p class=\"with\">with <a href=\"kushida-kikyou.html\">Kushida Kikyō<\/a> · <a href=\"nishino-takeko.html\">Nishino Takeko<\/a> · <a href=\"amikura-mako.html\">Amikura Mako<\/a><\/p><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kushida Kikyō<\/b> She reads Kushida&#x27;s pull on the group; hangs back.<span class=\"pg\">p.135–139<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nishino Takeko<\/b> They swap small talk on the bus rides.<span class=\"pg\">p.130–139<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Amikura Mako<\/b> She stands near Amikura during the map-app stupor.<span class=\"pg\">p.132<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-yamamura-miki-y2v8-p92-2\">← Before: Passing-mention records<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-yamamura-miki-y2v8-p162-1\">→ After: The morning; the snowball fight; the head hit<\/button><\/div><\/article>"},{"i":"sc-yamamura-miki-y2v8-p162-1","v":"y2v8","y":2,"o":24,"k":"spoken","w":"ayanokouji-kiyotaka kitou-hayato yano-koharu nishino-takeko kushida-kikyou yamamura-miki","q":"yamamura miki the morning  the snowball fight  the head hit final morning  she hears the snowball fight go up and goes quiet   she wants to watch  she watches the boys  match  gloveless  answering casual talk with minimal nods  ayanokoji joins her   ah  it seems so  she admits her own sadness isn t about her own self  i m not interested  sort of talk  she expresses gratitude to kushida  nishino  amikura  and acknowledges yamamura is invisible image  ayanokoji nudges her toward liking her own presence   i don t really know  i m not close to anyone in particular to begin with  and moreover  i ve hardly ever talked to sakayanagi san   little by little  i think kito kun s curses for ryuen kun are decreasing    no wait  that s her too   little by little  i think kito kun s curses for ryuen kun are decreasing    speaker yamamura   hers  hmm   let me re check  p 167 168   little by little  i think kito kun s curses for ryuen kun are decreasing  speaker  sequence  ak notices her attention drift to kito  she says this  attribute  yamamura   keep  she joins ayanokoji s team on the third match reluctantly  she d rather die than throw  she s hit square in the head by yano s snowball  she scrambles out  frustrated  she apologizes to ayanokoji   eh  eh  wow  i can t do that   i m sorry  i m just kidding  i brought my own gloves   i m sorry  i couldn t help you at all   yes  i wish i could ve tried harder  she waves him off as they part  she carries the kito possibility in her pocket  nothing resolved yet  a hunted person learning to accept being watched  she wants to try but can t  the trip changes how she watches herself  he rescues her from the match without being asked  she owes him  he owes her honesty  she considers him aloud  almost  ayanokoji hears it  class a s yano hits her in the head  she takes it manfully  they watch together  she came with kushida  kept her head down","h":"<article class=\"card\" id=\"sc-yamamura-miki-y2v8-p162-1\"><h3><span class=\"ttl\">The morning; the snowball fight; the head hit<\/span><span class=\"meta\">Y2V8 · p.162–174<\/span><\/h3><p class=\"setup\">Final morning; she hears the snowball fight go up and goes quiet — she wants to watch. She watches the boys&#x27; match, gloveless, answering casual talk with minimal nods; Ayanokōji joins her. She admits her own sadness isn&#x27;t about her own self (&quot;I&#x27;m not interested&quot; sort of talk); she expresses gratitude to Kushida, Nishino, Amikura, and acknowledges Yamamura-is-invisible image; Ayanokōji nudges her toward liking her own presence. She joins Ayanokōji&#x27;s team on the third match reluctantly; she&#x27;d rather die than throw; she&#x27;s hit square in the head by Yano&#x27;s snowball; she scrambles out, frustrated; she apologizes to Ayanokōji. She waves him off as they part; she carries the Kitō possibility in her pocket; nothing resolved yet.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"kitou-hayato.html\">Kitō Hayato<\/a> · <a href=\"yano-koharu.html\">Yano Koharu<\/a> · <a href=\"nishino-takeko.html\">Nishino Takeko<\/a> · <a href=\"kushida-kikyou.html\">Kushida Kikyō<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Ah, it seems so.”<span class=\"pg\">p.165<\/span><\/li><li class=\"q spoken\">“I don&#x27;t really know. I&#x27;m not close to anyone in particular to begin with, and moreover, I&#x27;ve hardly ever talked to Sakayanagi-san.”<span class=\"pg\">p.167<\/span><\/li><li class=\"q spoken\">“Little by little, I think Kitō-kun&#x27;s curses for Ryūen-kun are decreasing.” — no wait, that&#x27;s her too: &quot;`Little by little, I think Kitō-kun&#x27;s curses for Ryūen-kun are decreasing.&#x27;`&quot; — speaker Yamamura ✓ hers? Hmm — let me…”<span class=\"pg\">p.168<\/span><\/li><\/ul><details class=\"more\"><summary>11 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Little by little, I think Kitō-kun&#x27;s curses for Ryūen-kun are decreasing.” — no wait, that&#x27;s her too: &quot;`Little by little, I think Kitō-kun&#x27;s curses for Ryūen-kun are decreasing.&#x27;`&quot; — speaker Yamamura ✓ hers? Hmm — let me re-check: p.167–168: ““Little by little, I think Kitō-kun&#x27;s curses for Ryūen-kun are decreasing.” Speaker? Sequence: AK notices her attention drift to Kitō... she says this. Attribute: Yamamura ✓. Keep.<span class=\"pg\">p.168<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Eh, eh! Wow, I can&#x27;t do that.”<span class=\"pg\">p.169<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I&#x27;m sorry, I&#x27;m just kidding. I brought my own gloves.”<span class=\"pg\">p.165<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I&#x27;m sorry, I couldn&#x27;t help you at all.”<span class=\"pg\">p.172<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Yes. I wish I could&#x27;ve tried harder.”<span class=\"pg\">p.172<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> A hunted person learning to accept being watched; she wants to try but can&#x27;t; the trip changes how she watches herself.<span class=\"pg\">p.162–174<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> He rescues her from the match without being asked; she owes him; he owes her honesty.<span class=\"pg\">p.162–174<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kitō Hayato<\/b> She considers him aloud (almost); Ayanokōji hears it.<span class=\"pg\">p.167–168<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yano Koharu<\/b> Class A&#x27;s Yano hits her in the head; she takes it manfully.<span class=\"pg\">p.170–171<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nishino Takeko<\/b> They watch together.<span class=\"pg\">p.165<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kushida Kikyō<\/b> She came with Kushida; kept her head down.<span class=\"pg\">p.165–166<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-yamamura-miki-y2v8-p130-1\">← Before: The tour debate; hands in pockets<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-yamamura-miki-y2v8-p200-1\">→ After: Short Story &quot;Weak Presence&quot; (Yamamura POV)<\/button><\/div><\/article>"},{"i":"sc-yamamura-miki-y2v8-p200-1","v":"y2v8","y":2,"o":24,"k":"spoken","w":"ayanokouji-kiyotaka kushida-kikyou nishino-takeko amikura-mako yamamura-miki","q":"yamamura miki short story  weak presence   yamamura pov  the snowball fight  retold from her pov  she pre resolves to fade  then he is simply there  he asks about her gloves  her carefully built silence cracks on screen   hoo   yes   i m sorry  i m just kidding  i m carrying them with me   sure enough  does it not suit my style  she drains the last feeling in her chest   the shadow she has been all her life begins to suspect it might want more  the school trip becomes a hinge  she questions whether she still believes the trip was only  a school trip to investigate the enemy  not quoted   inferred from narration  the internal shift is the story s whole payload    a school trip to investigate the enemy  turns into a personal negotiation  he notices her  it changes nothing and everything  she belongs to him without meaning to  she credits kushida for seeing her at all  she credits nishino ditto  she credits amikura ditto","h":"<article class=\"card\" id=\"sc-yamamura-miki-y2v8-p200-1\"><h3><span class=\"ttl\">Short Story &quot;Weak Presence&quot; (Yamamura POV)<\/span><span class=\"meta\">Y2V8 · p.200–201<\/span><\/h3><p class=\"setup\">The snowball fight, retold from her POV: she pre-resolves to fade, then he is simply there; he asks about her gloves; her carefully built silence cracks on screen. She drains the last feeling in her chest — the shadow she has been all her life begins to suspect it might want more; the school trip becomes a hinge.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"kushida-kikyou.html\">Kushida Kikyō<\/a> · <a href=\"nishino-takeko.html\">Nishino Takeko<\/a> · <a href=\"amikura-mako.html\">Amikura Mako<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Hoo...”<span class=\"pg\">p.200<\/span><\/li><li class=\"q spoken\">“Yes.”<span class=\"pg\">p.200<\/span><\/li><li class=\"q spoken\">“I&#x27;m sorry, I&#x27;m just kidding. I&#x27;m carrying them with me.”<span class=\"pg\">p.200<\/span><\/li><\/ul><details class=\"more\"><summary>7 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Sure enough… does it not suit my style?”<span class=\"pg\">p.200<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> She questions whether she still believes the trip was only &quot;a school trip to investigate the enemy.&quot; Not quoted — inferred from narration.<span class=\"pg\">p.201<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The internal shift is the story&#x27;s whole payload — &quot;A school trip to investigate the enemy&quot; turns into a personal negotiation.<span class=\"pg\">p.201<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> He notices her; it changes nothing and everything; she belongs to him without meaning to.<span class=\"pg\">p.200–201<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kushida Kikyō<\/b> She credits Kushida for seeing her at all.<span class=\"pg\">p.200<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Nishino Takeko<\/b> She credits Nishino ditto.<span class=\"pg\">p.200<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Amikura Mako<\/b> She credits Amikura ditto.<span class=\"pg\">p.200<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-yamamura-miki-y2v8-p162-1\">← Before: The morning; the snowball fight; the head hit<\/button><\/div><\/article>"},{"i":"sc-yamamura-miki-y2v9_5-p128-1","v":"y2v9.5","y":2,"o":26,"k":"spoken","w":"ayanokouji-kiyotaka ryuuen-kakeru sakayanagi-arisu yamamura-miki","q":"yamamura miki yamamura  tailing ayanokoji ayanokoji catches her hiding in a blind spot near a vending machine  she admits  by silence  that she has been following him for about ten minutes   and the day before as well   but he tells her ryuen and katsuragi did not notice   what are you doing in a place like that   really  i felt like ryuen kun was trying to lure me out  stealthy and anxious   she tails him out of concern about ryuen s trap and is flustered at being caught  she follows him  he calls her out gently  she fears he was trying to lure ayanokoji out  he catches her hiding by a vending machine  she s been following him for ten minutes   yesterday too  he tells her he won t report her to ryuen  ryuen reappears  applauding  she s sakayanagi s spy  not a ryuen plant  katsuragi figures it out too  ryuen lets her go  telling her to visit his room alone anytime  he finds her by the vending machines  she nearly drops a bottled tea  denies gps  he gives her the same deal he gives everyone in the group chat  he points her to the truth  she confesses self worth concerns  he encourages her  she overhears kei and sato  his promise not to let her be expelled finally breaks her guard  he tells her to report it honestly  she types the message  i ve been caught by ryuen kun and katsuragi kun  i ll tell you the details by call  and sends it  excuses herself in a hurry   you ve been following me for about 10 minutes  right   should i not keep quiet about it   we ll keep the fact that we noticed you a secret  he catches her and teases  he chooses to keep her hunting rather than give her up  sends her the message  i ve been caught    the report to the class leader","h":"<article class=\"card\" id=\"sc-yamamura-miki-y2v9_5-p128-1\"><h3><span class=\"ttl\">Yamamura: tailing Ayanokōji<\/span><span class=\"meta\">Y2V9.5 · p.128–143<\/span><\/h3><p class=\"setup\">Ayanokōji catches her hiding in a blind spot near a vending machine; she admits, by silence, that she has been following him for about ten minutes — and the day before as well — but he tells her Ryūen and Katsuragi did not notice. He catches her hiding by a vending machine; she&#x27;s been following him for ten minutes — yesterday too; he tells her he won&#x27;t report her to Ryūen. Ryūen reappears, applauding; she&#x27;s Sakayanagi&#x27;s spy, not a Ryūen plant; Katsuragi figures it out too; Ryūen lets her go, telling her to visit his room alone anytime. He finds her by the vending machines; she nearly drops a bottled tea; denies GPS; he gives her the same deal he gives everyone in the group chat; he points her to the truth. She confesses self-worth concerns; he encourages her; she overhears Kei and Satō; his promise not to let her be expelled finally breaks her guard; he tells her to report it honestly. She types the message &quot;I&#x27;ve been caught by Ryūen-kun and Katsuragi-kun. I&#x27;ll tell you the details by call.&quot; and sends it; excuses herself in a hurry.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"ryuuen-kakeru.html\">Ryūen Kakeru<\/a> · <a href=\"sakayanagi-arisu.html\">Sakayanagi Arisu<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;What are you doing in a place like that?&quot;<span class=\"pg\">p.128<\/span><\/li><li class=\"q spoken\">&quot;Really? I felt like Ryūen-kun was trying to lure me out...&quot;<span class=\"pg\">p.129<\/span><\/li><li class=\"q spoken\">&quot;You&#x27;ve been following me for about 10 minutes, right?&quot;<span class=\"pg\">p.131<\/span><\/li><\/ul><details class=\"more\"><summary>7 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Stealthy and anxious — she tails him out of concern about Ryūen&#x27;s trap and is flustered at being caught.<span class=\"pg\">p.128–129<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> She follows him; he calls her out gently.<span class=\"pg\">p.128–129<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> She fears he was trying to lure Ayanokōji out.<span class=\"pg\">p.129<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Should I not keep quiet about it...?&quot;<span class=\"pg\">p.138<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;We&#x27;ll keep the fact that we noticed you a secret.&quot;<span class=\"pg\">p.143<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> He catches her and teases; he chooses to keep her hunting rather than give her up.<span class=\"pg\">p.132–133<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> Sends her the message &quot;I&#x27;ve been caught...&quot; — the report to the class leader.<span class=\"pg\">p.142<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-yamamura-miki-y2v10-p9-1","v":"y2v10","y":2,"o":28,"k":"","w":"yamamura-miki","q":"yamamura miki yamamura miki mentioned in passing named in this volume  passing mention  locator pages  p 138  p 146  p 157 160  p 193 196  p 209  not line by line verified  substring false positives possible  not a scene presence  passing mention only","h":"<article class=\"card\" id=\"sc-yamamura-miki-y2v10-p9-1\"><h3><span class=\"ttl\">yamamura-miki mentioned in passing<\/span><span class=\"meta\">Y2V10 · p.9-235<\/span><\/h3><p class=\"setup\">Named in this volume.<\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Passing mention (locator pages: p.138, p.146, p.157-160, p.193-196, p.209; not line-by-line verified; substring false positives possible). Not a scene presence.<span class=\"pg\">p.9<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> Passing mention only.<span class=\"pg\">p.9<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-yamamura-miki-y2v10-p138-1\">→ After: Ch.6: Out in the final turn of the first half<\/button><\/div><\/article>"},{"i":"sc-yamamura-miki-y2v10-p138-1","v":"y2v10","y":2,"o":28,"k":"","w":"yamamura-miki","q":"yamamura miki ch 6  out in the final turn of the first half eliminated in the last turn of the first half  the first half scoreboard shows sakayanagi s class at 29 points with two eliminated   kamuro  yamamura  his name is listed with the rest of the cluster ryuen targets  no dialogue attributed to him on these pages  the page does not record his last answer   yamamura  in the nominee cluster and the  yamamura from sakayanagi s class  elimination list both refer to the same individual   same class  same exam","h":"<article class=\"card\" id=\"sc-yamamura-miki-y2v10-p138-1\"><h3><span class=\"ttl\">Ch.6: Out in the final turn of the first half<\/span><span class=\"meta\">Y2V10 · p.138, 146<\/span><\/h3><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> Eliminated in the last turn of the first half; the first half scoreboard shows Sakayanagi&#x27;s class at 29 points with two eliminated — Kamuro, Yamamura.<span class=\"pg\">p.138<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> His name is listed with the rest of the cluster Ryūen targets.<span class=\"pg\">p.146<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> No dialogue attributed to him on these pages; the page does not record his last answer.<span class=\"pg\">p.138<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> &quot;Yamamura&quot; in the nominee cluster and the &quot;Yamamura from Sakayanagi’s class&quot; elimination list both refer to the same individual — same class, same exam.<span class=\"pg\">p.146<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-yamamura-miki-y2v10-p9-1\">← Before: yamamura-miki mentioned in passing<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-yamamura-miki-y2v10-p157-1\">→ After: Ch.6: passing mentions (locator cross-check)<\/button><\/div><\/article>"},{"i":"sc-yamamura-miki-y2v10-p157-1","v":"y2v10","y":2,"o":28,"k":"","w":"yamamura-miki","q":"yamamura miki ch 6  passing mentions  locator cross check  passing mention   close to having kamuro or yamamura expelled  if kito or hashimoto messes up  passing mention   fully protect kamuro or yamamura  passing mention  see p 159  passing mention   instead  only push key players like kamuro or yamamura  as well as kito or","h":"<article class=\"card\" id=\"sc-yamamura-miki-y2v10-p157-1\"><h3><span class=\"ttl\">Ch.6: passing mentions (locator cross-check)<\/span><span class=\"meta\">Y2V10 · p.157–160<\/span><\/h3><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> Passing mention — close to having Kamuro or Yamamura expelled. If Kitō or Hashimoto messes up,<span class=\"pg\">p.157<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> Passing mention — fully protect Kamuro or Yamamura.<span class=\"pg\">p.158<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> Passing mention (see p.159).<span class=\"pg\">p.159<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> Passing mention — instead, only push key players like Kamuro or Yamamura, as well as Kitō or<span class=\"pg\">p.160<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-yamamura-miki-y2v10-p138-1\">← Before: Ch.6: Out in the final turn of the first half<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-yamamura-miki-y2v10-p193-1\">→ After: Ch.7: The last to draw<\/button><\/div><\/article>"},{"i":"sc-yamamura-miki-y2v10-p193-1","v":"y2v10","y":2,"o":28,"k":"spoken","w":"kamuro-masumi yamamura-miki","q":"yamamura miki ch 7  the last to draw she draws last alongside kamuro  her hand trembles too much to move on her own  kamuro must forcibly guide her left hand to clutch the lot  kamuro stops her   sakayanagi says those who refuse to draw will be expelled  she asks to draw simultaneously with kamuro  they open their hands together  the colored paper is in kamuro s  she stays   geez  then i ll draw it first  is that okay   don t hold a grudge  she remains  her shoulder patted by kamuro  who drew the colored paper  her survival feels neither triumphant nor grateful  she is one of the five students eliminated in the special exam  the lottery spares her  not kamuro","h":"<article class=\"card\" id=\"sc-yamamura-miki-y2v10-p193-1\"><h3><span class=\"ttl\">Ch.7: The last to draw<\/span><span class=\"meta\">Y2V10 · p.193–196<\/span><\/h3><p class=\"setup\">She draws last alongside Kamuro; her hand trembles too much to move on her own; Kamuro must forcibly guide her left hand to clutch the lot. Kamuro stops her — Sakayanagi says those who refuse to draw will be expelled; she asks to draw simultaneously with Kamuro. They open their hands together; the colored paper is in Kamuro&#x27;s; she stays. She remains; her shoulder patted by Kamuro, who drew the colored paper; her survival feels neither triumphant nor grateful.<\/p><p class=\"with\">with <a href=\"kamuro-masumi.html\">Kamuro Masumi<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Kamuro Masumi<\/b> “Geez. Then I’ll draw it first. Is that okay?”<span class=\"pg\">p.195<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Kamuro Masumi<\/b> “Don’t hold a grudge.”<span class=\"pg\">p.195<\/span><\/li><\/ul><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> She is one of the five students eliminated in the special exam; the lottery spares her, not Kamuro.<span class=\"pg\">p.193<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-yamamura-miki-y2v10-p157-1\">← Before: Ch.6: passing mentions (locator cross-check)<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-yamamura-miki-y2v10-p209-1\">→ After: Ch.7: passing mentions (locator cross-check)<\/button><\/div><\/article>"},{"i":"sc-yamamura-miki-y2v10-p209-1","v":"y2v10","y":2,"o":28,"k":"","w":"yamamura-miki","q":"yamamura miki ch 7  passing mentions  locator cross check  passing mention  see p 209","h":"<article class=\"card\" id=\"sc-yamamura-miki-y2v10-p209-1\"><h3><span class=\"ttl\">Ch.7: passing mentions (locator cross-check)<\/span><span class=\"meta\">Y2V10 · p.209–209<\/span><\/h3><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> Passing mention (see p.209).<span class=\"pg\">p.209<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-yamamura-miki-y2v10-p193-1\">← Before: Ch.7: The last to draw<\/button><\/div><\/article>"},{"i":"sc-yamamura-miki-y2v11-p10-1","v":"y2v11","y":2,"o":30,"k":"narration","w":"sakayanagi-arisu yamamura-miki","q":"yamamura miki prologue  yamamura s monologue her own pov  addressed to no one  in kindergarten  elementary and junior high she spent her life alone  she was inconspicuous and lacking presence   too forgettable to be liked  too forgettable to be hated   realized that i was alone   it wasn t that anyone particularly disliked me   i just didn t catch anyone s eye   i was inconspicuous  lacking presence   before anyone could like me  they couldn t even hate me   that was why i was always alone   even after becoming a high school student  nothing changed   but i thought that was okay   i forced myself to believe that it was my strength   i thought it would be okay to live quietly alone even as an adult   until this day  two unattributed lines surface in her monologue as remembered speech   after all  i don t think losing suits sakayanagi san  and  why don t you try telling her  no one has the right to criticize your actions    the speaker is not identified on these pages  recorded as unattributed recollection  the prologue is interior monologue  no other named on page presence  sakayanagi is referenced  never present  the remembered line being turned over  that losing does not suit sakayanagi  the trigger of the monologue is the lottery scene alluded to later in ch 7","h":"<article class=\"card\" id=\"sc-yamamura-miki-y2v11-p10-1\"><h3><span class=\"ttl\">Prologue: Yamamura&#x27;s monologue<\/span><span class=\"meta\">Y2V11 · p.10<\/span><\/h3><p class=\"setup\">Her own POV, addressed to no one: in kindergarten, elementary and junior high she spent her life alone; she was inconspicuous and lacking presence — too forgettable to be liked, too forgettable to be hated.<\/p><p class=\"with\">with <a href=\"sakayanagi-arisu.html\">Sakayanagi Arisu<\/a><\/p><ul class=\"lines\"><li class=\"q narration\">“REALIZED THAT I was alone.”<span class=\"pg\">p.10<\/span><\/li><li class=\"q narration\">“It wasn&#x27;t that anyone particularly disliked me.”<span class=\"pg\">p.10<\/span><\/li><li class=\"q narration\">“I just didn&#x27;t catch anyone&#x27;s eye.”<span class=\"pg\">p.10<\/span><\/li><\/ul><details class=\"more\"><summary>11 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Narration<\/span> “I was inconspicuous, lacking presence.”<span class=\"pg\">p.10<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> “Before anyone could like me, they couldn&#x27;t even hate me.”<span class=\"pg\">p.10<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> “That was why I was always alone.”<span class=\"pg\">p.10<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> “Even after becoming a high school student, nothing changed.”<span class=\"pg\">p.10<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> “But I thought that was okay.”<span class=\"pg\">p.10<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> “I forced myself to believe that it was my strength…”<span class=\"pg\">p.10<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> “I thought it would be okay to live quietly alone even as an adult.”<span class=\"pg\">p.10<\/span><\/li><li><span class=\"mlabel\">Narration<\/span> “—Until this day.”<span class=\"pg\">p.10<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Two unattributed lines surface in her monologue as remembered speech: “...After all... I don&#x27;t think losing suits Sakayanagi-san...” and “Why don&#x27;t you try telling her? No one has the right to criticize your actions.” — the speaker is not identified on these pages; recorded as unattributed recollection.<span class=\"pg\">p.10<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The Prologue is interior monologue; no other named on-page presence. Sakayanagi is referenced, never present.<span class=\"pg\">p.10<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> The remembered line being turned over: that losing does not suit Sakayanagi; the trigger of the monologue is the lottery scene alluded to later in Ch.7.<span class=\"pg\">p.10<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-yamamura-miki-y2v11-p30-1\">→ After: Ch.1: Three or four items she can&#x27;t refuse<\/button><\/div><\/article>"},{"i":"sc-yamamura-miki-y2v11-p30-1","v":"y2v11","y":2,"o":30,"k":"spoken","w":"hashimoto-masayoshi morishita-ai yamamura-miki","q":"yamamura miki ch 1  three or four items she can t refuse in the convenience store beverage section she collides almost with kiyotaka  she had been watching hashimoto on the emergency stairs  she ends up shopping with the group  unable to refuse morishita s recommendations   ah  h hello   um  i  i use the convenience store quite a bit  about once or twice a week  but i don t stand out  i m sorry   eh  um  yes  if that s okay with you  i mean   no  um  i m yamamura  she had been watching him on the emergency stairs  he probes her store habit in awkward fashion  morishita overwhelms her with recommendations  she gives in and buys three or four items  kiyotaka infers she was watching hashimoto  perhaps for sakayanagi  there is no reason to think she was watching him  morishita notes it s rare to see yamamura talking to a boy  her own classmates struggle with her","h":"<article class=\"card\" id=\"sc-yamamura-miki-y2v11-p30-1\"><h3><span class=\"ttl\">Ch.1: Three or four items she can&#x27;t refuse<\/span><span class=\"meta\">Y2V11 · p.30–33<\/span><\/h3><p class=\"setup\">In the convenience-store beverage section she collides almost with Kiyotaka; she had been watching Hashimoto on the emergency stairs. She ends up shopping with the group; unable to refuse Morishita&#x27;s recommendations.<\/p><p class=\"with\">with <a href=\"hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a> · <a href=\"morishita-ai.html\">Morishita Ai<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Ah... H-hello...”<span class=\"pg\">p.30<\/span><\/li><li class=\"q spoken\">“Um, I... I use the convenience store quite a bit... about once or twice a week... but I don&#x27;t stand out... I&#x27;m sorry.”<span class=\"pg\">p.30<\/span><\/li><li class=\"q spoken\">“Eh, um, yes... if that&#x27;s okay with you... I mean...”<span class=\"pg\">p.31<\/span><\/li><\/ul><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “No, um... I&#x27;m Yamamura...”<span class=\"pg\">p.32<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hashimoto Masayoshi<\/b> She had been watching him on the emergency stairs; he probes her store habit in awkward fashion.<span class=\"pg\">p.30–32<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Morishita Ai<\/b> Morishita overwhelms her with recommendations; she gives in and buys three or four items.<span class=\"pg\">p.31–33<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Kiyotaka infers she was watching Hashimoto, perhaps for Sakayanagi; there is no reason to think she was watching him.<span class=\"pg\">p.30<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Morishita notes it&#x27;s rare to see Yamamura talking to a boy; her own classmates struggle with her.<span class=\"pg\">p.31<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-yamamura-miki-y2v11-p10-1\">← Before: Prologue: Yamamura&#x27;s monologue<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-yamamura-miki-y2v11-p46-1\">→ After: Ch.2: The seventeenth in the count<\/button><\/div><\/article>"},{"i":"sc-yamamura-miki-y2v11-p46-1","v":"y2v11","y":2,"o":30,"k":"spoken","w":"hashimoto-masayoshi shiina-hiyori yamamura-miki","q":"yamamura miki ch 2  the seventeenth in the count group 20 gathers at the inn  hashimoto s head count misses her  hiyori talks with her  she stiffens   no  i m sorry   ah that  you re completely different from what i thought   i thought you were more  indifferent   i m sorry  i m not good at talking to people  so i might ve said something rude   ayanokoji kun  being overlooked by hashimoto and unnoticed by kiryuin  hiyori draws her out  she expected hiyori to be more indifferent  he apologizes for missing her in the count  hiyori takes her hand and says it s thanks to ayanokoji kun that she loves talking","h":"<article class=\"card\" id=\"sc-yamamura-miki-y2v11-p46-1\"><h3><span class=\"ttl\">Ch.2: The seventeenth in the count<\/span><span class=\"meta\">Y2V11 · p.46–49<\/span><\/h3><p class=\"setup\">Group 20 gathers at the inn; Hashimoto&#x27;s head-count misses her; Hiyori talks with her; she stiffens.<\/p><p class=\"with\">with <a href=\"hashimoto-masayoshi.html\">Hashimoto Masayoshi<\/a> · <a href=\"shiina-hiyori.html\">Shiina Hiyori<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“No... I&#x27;m sorry.”<span class=\"pg\">p.47<\/span><\/li><li class=\"q spoken\">“Ah—that... you&#x27;re completely different from what I thought...”<span class=\"pg\">p.48<\/span><\/li><li class=\"q spoken\">“I thought you were more... indifferent...”<span class=\"pg\">p.48<\/span><\/li><\/ul><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “I&#x27;m sorry. I&#x27;m not good at talking to people, so I might’ve said something rude...”<span class=\"pg\">p.48<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Ayanokōji-kun...?”<span class=\"pg\">p.48<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Being overlooked by Hashimoto and unnoticed by Kiryūin; Hiyori draws her out; she expected Hiyori to be more indifferent.<span class=\"pg\">p.47–48<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hashimoto Masayoshi<\/b> He apologizes for missing her in the count.<span class=\"pg\">p.47<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shiina Hiyori<\/b> Hiyori takes her hand and says it&#x27;s thanks to Ayanokōji-kun that she loves talking.<span class=\"pg\">p.48<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-yamamura-miki-y2v11-p30-1\">← Before: Ch.1: Three or four items she can&#x27;t refuse<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-yamamura-miki-y2v11-p60-1\">→ After: Ch.2: The chance encounter<\/button><\/div><\/article>"},{"i":"sc-yamamura-miki-y2v11-p60-1","v":"y2v11","y":2,"o":30,"k":"","w":"yamamura-miki","q":"yamamura miki ch 2  the chance encounter the break room  their paths cross   when hashimoto and morishita stopped by the convenience store  they ran into yamamura  and kiryuin happened to be there at the same time    the choosing of the group  she is the reason  named in dialogue  not present on these pages","h":"<article class=\"card\" id=\"sc-yamamura-miki-y2v11-p60-1\"><h3><span class=\"ttl\">Ch.2: The chance encounter<\/span><span class=\"meta\">Y2V11 · p.60<\/span><\/h3><p class=\"setup\">The break room; their paths cross.<\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> “When Hashimoto and Morishita stopped by the convenience store, they ran into Yamamura, and Kiryūin happened to be there at the same time.” — the choosing of the group; she is the reason.<span class=\"pg\">p.60<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> Named in dialogue; not present on these pages.<span class=\"pg\">p.60<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-yamamura-miki-y2v11-p46-1\">← Before: Ch.2: The seventeenth in the count<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-yamamura-miki-y2v11-p111-1\">→ After: Ch.4: One of the only girls in Class A he interacts with<\/button><\/div><\/article>"},{"i":"sc-yamamura-miki-y2v11-p111-1","v":"y2v11","y":2,"o":30,"k":"","w":"yamamura-miki","q":"yamamura miki ch 4  one of the only girls in class a he interacts with sakayanagi s search for a kamuro successor runs into the same two names   the only girls in class a that i interacted with were yamamura and morishita  both of them had their strengths  but they weren t suitable for taking care of sakayanagi    unattributed narration  named as one of the two class a girls kiyotaka knows  not present on these pages","h":"<article class=\"card\" id=\"sc-yamamura-miki-y2v11-p111-1\"><h3><span class=\"ttl\">Ch.4: One of the only girls in Class A he interacts with<\/span><span class=\"meta\">Y2V11 · p.111<\/span><\/h3><p class=\"setup\">Sakayanagi&#x27;s search for a Kamuro successor runs into the same two names.<\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> “The only girls in Class A that I interacted with were Yamamura and Morishita. Both of them had their strengths, but they weren&#x27;t suitable for taking care of Sakayanagi.” — unattributed narration.<span class=\"pg\">p.111<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> Named as one of the two Class A girls Kiyotaka knows; not present on these pages.<span class=\"pg\">p.111<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-yamamura-miki-y2v11-p60-1\">← Before: Ch.2: The chance encounter<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-yamamura-miki-y2v11-p120-1\">→ After: Ch.5: The support role<\/button><\/div><\/article>"},{"i":"sc-yamamura-miki-y2v11-p120-1","v":"y2v11","y":2,"o":30,"k":"","w":"yamamura-miki","q":"yamamura miki ch 5  the support role the rest area  she is named   support role  yamamura is participating in the matches  and her honesty is helpful    his honest report   however  yamamura had seemed listless lately  but i didn t mention that    his silence  named in dialogue  not present on these pages","h":"<article class=\"card\" id=\"sc-yamamura-miki-y2v11-p120-1\"><h3><span class=\"ttl\">Ch.5: The support role<\/span><span class=\"meta\">Y2V11 · p.120–121<\/span><\/h3><p class=\"setup\">The rest area; she is named.<\/p><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> “support role. Yamamura is participating in the matches, and her honesty is helpful.” — his honest report.<span class=\"pg\">p.120<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> “However, Yamamura had seemed listless lately, but I didn&#x27;t mention that.” — his silence.<span class=\"pg\">p.121<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> Named in dialogue; not present on these pages.<span class=\"pg\">p.120–121<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-yamamura-miki-y2v11-p111-1\">← Before: Ch.4: One of the only girls in Class A he interacts with<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-yamamura-miki-y2v11-p135-1\">→ After: Ch.5: Watching from the corner<\/button><\/div><\/article>"},{"i":"sc-yamamura-miki-y2v11-p135-1","v":"y2v11","y":2,"o":30,"k":"spoken","w":"shiina-hiyori morishita-ai ayanokouji-kiyotaka yamamura-miki","q":"yamamura miki ch 5  watching from the corner the girls room  she watches the room  she refuses to play  hiyori coaxes her in   um  i ll  watch   but  she watches the girls over cards  she refuses to join  she joins only when hiyori asks  her name is botched as  yamashita senpai  she does not correct it  everyone skips her turn  hiyori pulls her in  she is treated like an honorary member  she is not even a player in morishita s advance strategy homework  he alone notices her invisibility  he points it out","h":"<article class=\"card\" id=\"sc-yamamura-miki-y2v11-p135-1\"><h3><span class=\"ttl\">Ch.5: Watching from the corner<\/span><span class=\"meta\">Y2V11 · p.135–142<\/span><\/h3><p class=\"setup\">The girls&#x27;room; she watches the room; she refuses to play; Hiyori coaxes her in.<\/p><p class=\"with\">with <a href=\"shiina-hiyori.html\">Shiina Hiyori<\/a> · <a href=\"morishita-ai.html\">Morishita Ai<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Um... I&#x27;ll... watch.”<span class=\"pg\">p.137<\/span><\/li><li class=\"q spoken\">“But...”<span class=\"pg\">p.141<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> She watches the girls over cards; she refuses to join; she joins only when Hiyori asks; her name is botched as “Yamashita-senpai”; she does not correct it; everyone skips her turn.<span class=\"pg\">p.135–142<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shiina Hiyori<\/b> Hiyori pulls her in; she is treated like an honorary member.<span class=\"pg\">p.137–141<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Morishita Ai<\/b> She is not even a player in Morishita&#x27;s advance-strategy homework.<span class=\"pg\">p.135–141<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> He alone notices her invisibility; he points it out.<span class=\"pg\">p.135–142<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-yamamura-miki-y2v11-p120-1\">← Before: Ch.5: The support role<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-yamamura-miki-y2v11-p146-1\">→ After: Ch.6: The small presence<\/button><\/div><\/article>"},{"i":"sc-yamamura-miki-y2v11-p146-1","v":"y2v11","y":2,"o":30,"k":"","w":"yamamura-miki","q":"yamamura miki ch 6  the small presence the morning training  the small presence question floats in the air  nobody answers it out loud   who comes to mind when you think of a student with a small presence    horikita answers  you  ayanokoji kun    he says to himself  all of these characteristics fit yamamura  named in the narration as the archetype of invisibility  not present on these pages","h":"<article class=\"card\" id=\"sc-yamamura-miki-y2v11-p146-1\"><h3><span class=\"ttl\">Ch.6: The small presence<\/span><span class=\"meta\">Y2V11 · p.146–147<\/span><\/h3><p class=\"setup\">The morning training; the small-presence question floats in the air; nobody answers it out loud.<\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> “Who comes to mind when you think of a student with a small presence?” — Horikita answers “You, Ayanokōji-kun.” — he says to himself: all of these characteristics fit Yamamura.<span class=\"pg\">p.146–147<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> Named in the narration as the archetype of invisibility; not present on these pages.<span class=\"pg\">p.146–147<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-yamamura-miki-y2v11-p135-1\">← Before: Ch.5: Watching from the corner<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-yamamura-miki-y2v11-p168-1\">→ After: Ch.7: The vending machine<\/button><\/div><\/article>"},{"i":"sc-yamamura-miki-y2v11-p168-1","v":"y2v11","y":2,"o":30,"k":"spoken","w":"ayanokouji-kiyotaka sakayanagi-arisu shiina-hiyori yamamura-miki","q":"yamamura miki ch 7  the vending machine past 11 p m  long past lights out  hiyori texts ayanokoji that she is missing  he finds her leaning against the vending machine   wh wh wh why are you here   i was confident that  i wouldn t be found  but if you found me  i can t use that excuse  can i   yes  when i listen to the sound of the vending machine  the unnecessary voices in my mind disappear   usually  they stop immediately and it s resolved  usually   it s not about liking or disliking  i just  don t have that kind of experience   you too  ayanokoji kun  but to me  you seem normal  you seem to have a lot of friends  and shiina san too  she s bright and cute  i m jealous   no  i m fine   i m  probably scared  of voicing my thoughts  and of those thoughts spreading unintentionally  i m scared of being known   since the last special exam ended  i ve had one question in my mind   when i hesitated to draw a lot  sakayanagi san said she would stop the lottery  if you didn t have the courage to draw a lot  it was the same as abstaining   i strongly felt that sakayanagi san wanted me to withdraw at that moment   i understand that it can t be helped  at least  when comparing me and kamuro san  the value was clear  i didn t wish to have special treatment  i didn t even want to be greedy and wish to be considered a friend  but  i was shocked to know that my existence was something that could be discarded in an instant  even though she used me  saying i was a valuable person   sakayanagi san doesn t suit losing  i don t want to see her struggle in the end of year exam  i hope she wins   as a result  tokito kun was  forcibly restrained and threatened by ryuen kun and his group   what if  what if  she doesn t even want to listen to me  she confesses to him the one question her mind keeps returning to   the survival and elimination exam   the draw  sakayanagi s verdict  being the one sakayanagi wanted to discard  the conversation includes the camp s lottery and the kamuro comparison  he offers   i ll get stuck in between some vending machines and talk it over    she looks at the vending machine shyly and nods  he finds her  he listens for hours  he promises to stand between her and sakayanagi  the two wishes  to know what sakayanagi thought of her then  and what she thinks of her now  and that sakayanagi  who doesn t suit losing  should not struggle in the end of year exam  her disappearance triggers hiyori s worried text  hiyori stays in the room as lookout","h":"<article class=\"card\" id=\"sc-yamamura-miki-y2v11-p168-1\"><h3><span class=\"ttl\">Ch.7: The vending machine<\/span><span class=\"meta\">Y2V11 · p.168–176<\/span><\/h3><p class=\"setup\">Past 11 p.m., long past lights-out; Hiyori texts Ayanokōji that she is missing; he finds her leaning against the vending machine.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"sakayanagi-arisu.html\">Sakayanagi Arisu<\/a> · <a href=\"shiina-hiyori.html\">Shiina Hiyori<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Wh-wh-wh-why are you here...?”<span class=\"pg\">p.170<\/span><\/li><li class=\"q spoken\">“I was confident that… I wouldn&#x27;t be found… but if you found me, I can&#x27;t use that excuse, can I…?”<span class=\"pg\">p.170<\/span><\/li><li class=\"q spoken\">“Yes. When I listen to the sound of the vending machine, the unnecessary voices in my mind disappear...”<span class=\"pg\">p.170<\/span><\/li><\/ul><details class=\"more\"><summary>17 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Usually, they stop immediately and it&#x27;s resolved… usually...”<span class=\"pg\">p.170<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “It&#x27;s not about liking or disliking, I just… don&#x27;t have that kind of experience...”<span class=\"pg\">p.171<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You too, Ayanokōji-kun? But to me… you seem normal. You seem to have a lot of friends. And Shiina-san too. She&#x27;s bright and cute… I&#x27;m jealous...”<span class=\"pg\">p.171<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “...No. I&#x27;m fine.”<span class=\"pg\">p.171<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I&#x27;m… probably scared. Of voicing my thoughts. And of those thoughts spreading unintentionally. I&#x27;m scared of being known...”<span class=\"pg\">p.172<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Since the last special exam ended, I&#x27;ve had one question in my mind...”<span class=\"pg\">p.172<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “When I hesitated to draw a lot, Sakayanagi-san said she would stop the lottery. If you didn&#x27;t have the courage to draw a lot, it was the same as abstaining...”<span class=\"pg\">p.173<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I strongly felt that Sakayanagi-san wanted me to withdraw at that moment.”<span class=\"pg\">p.173<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I understand that it can&#x27;t be helped. At least, when comparing me and Kamuro-san, the value was clear. I didn&#x27;t wish to have special treatment. I didn&#x27;t even want to be greedy and wish to be considered a friend. But... I was shocked to know that my existence was something that could be discarded in an instant... even though she used me, saying I was a valuable person...”<span class=\"pg\">p.173<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Sakayanagi-san doesn&#x27;t suit losing... I don&#x27;t want to see her struggle in the end-of-year exam... I hope she wins.”<span class=\"pg\">p.173<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “As a result, Tokitō-kun was... forcibly restrained and threatened by Ryūen-kun and his group.”<span class=\"pg\">p.174<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What if... what if... she doesn&#x27;t even want to listen to me...?”<span class=\"pg\">p.176<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> She confesses to him the one question her mind keeps returning to — the survival and elimination exam — the draw; Sakayanagi&#x27;s verdict; being the one Sakayanagi wanted to discard; the conversation includes the camp&#x27;s lottery and the Kamuro comparison.<span class=\"pg\">p.172–174<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> He offers: “I&#x27;ll get stuck in between some vending machines and talk it over.” — she looks at the vending machine shyly and nods.<span class=\"pg\">p.176<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> He finds her; he listens for hours; he promises to stand between her and Sakayanagi.<span class=\"pg\">p.168–176<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> The two wishes: to know what Sakayanagi thought of her then, and what she thinks of her now; and that Sakayanagi, who doesn&#x27;t suit losing, should not struggle in the end-of-year exam.<span class=\"pg\">p.172–176<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shiina Hiyori<\/b> Her disappearance triggers Hiyori&#x27;s worried text; Hiyori stays in the room as lookout.<span class=\"pg\">p.168<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-yamamura-miki-y2v11-p146-1\">← Before: Ch.6: The small presence<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-yamamura-miki-y2v11-p188-1\">→ After: Ch.8: The dog park<\/button><\/div><\/article>"},{"i":"sc-yamamura-miki-y2v11-p188-1","v":"y2v11","y":2,"o":30,"k":"","w":"sakayanagi-arisu yamamura-miki","q":"yamamura miki ch 8  the dog park the morning everything ends  she waits at the dog park in the cold for 20 minutes  the girl who always waits for others finally gets to wait for herself  she is in sight from the bench from the start  he positions her as the end goal  her waiting is patient and anxious  sakayanagi walks in on her own after he pushes her back  the two see each other  the scene closes without a single line of dialogue  the end of the long thread   the lottery  the verdict  the forgiveness  the two finally meet on their own terms","h":"<article class=\"card\" id=\"sc-yamamura-miki-y2v11-p188-1\"><h3><span class=\"ttl\">Ch.8: The dog park<\/span><span class=\"meta\">Y2V11 · p.188–193<\/span><\/h3><p class=\"setup\">The morning everything ends; she waits at the dog park in the cold for 20 minutes; the girl who always waits for others finally gets to wait for herself.<\/p><p class=\"with\">with <a href=\"sakayanagi-arisu.html\">Sakayanagi Arisu<\/a><\/p><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> She is in sight from the bench from the start; he positions her as the end goal; her waiting is patient and anxious.<span class=\"pg\">p.188<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Sakayanagi walks in on her own after he pushes her back; the two see each other; the scene closes without a single line of dialogue.<span class=\"pg\">p.193<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> The end of the long thread — the lottery, the verdict, the forgiveness; the two finally meet on their own terms.<span class=\"pg\">p.188–193<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-yamamura-miki-y2v11-p168-1\">← Before: Ch.7: The vending machine<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-yamamura-miki-y2v11-p206-1\">→ After: Epilogue: The inseparable pair<\/button><\/div><\/article>"},{"i":"sc-yamamura-miki-y2v11-p206-1","v":"y2v11","y":2,"o":30,"k":"","w":"yamamura-miki","q":"yamamura miki epilogue  the inseparable pair the career counseling room  her fall from grace   she felt a change in her emotional switch within her  starting with the incident involving kamuro and yamamura    the origin of her change  named in dialogue  not present on these pages","h":"<article class=\"card\" id=\"sc-yamamura-miki-y2v11-p206-1\"><h3><span class=\"ttl\">Epilogue: The inseparable pair<\/span><span class=\"meta\">Y2V11 · p.206<\/span><\/h3><p class=\"setup\">The career counseling room; her fall from grace.<\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> “She felt a change in her emotional switch within her, starting with the incident involving Kamuro and Yamamura.” — the origin of her change.<span class=\"pg\">p.206<\/span><\/li><li><span class=\"mlabel\">Mentioned<\/span> Named in dialogue; not present on these pages.<span class=\"pg\">p.206<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-yamamura-miki-y2v11-p188-1\">← Before: Ch.8: The dog park<\/button><\/div><\/article>"},{"i":"sc-yamamura-miki-y2v12-p44-1","v":"y2v12","y":2,"o":31,"k":"spoken","w":"ayanokouji-kiyotaka sakayanagi-arisu yamamura-miki","q":"yamamura miki ch 2  the rest area vending machines late friday evening  a rest area on the second floor of keyaki mall  she stands in front of a lined up vending machine  he stops by pretending to choose a product  tells her he hoped to find her there   how have things been with sakayanagi since then   we ve had more opportunities to talk than before   i stopped by hoping you would be here  yamamura  actually  there s something i want to ask  he asks about an unnamed matter that does not involve sakayanagi  she dodges a clear answer  then takes out her phone and plays a silent surveillance video dated december 26  7 pm  keyaki mall   two people interacting closely  cautious of their surroundings  she gives the video of the one person matching his description   the only person i found during my investigation that matches what you re talking about is this person   i hope it helps  nothing in the text names the two people in the video  the names are never printed on these pages  he uses the clip to summon matsushita the next step  member of class a known for surveillance work  she gathers the information for sakayanagi  per this volume s later reveal","h":"<article class=\"card\" id=\"sc-yamamura-miki-y2v12-p44-1\"><h3><span class=\"ttl\">Ch.2: The rest-area vending machines<\/span><span class=\"meta\">Y2V12 · p.44–45<\/span><\/h3><p class=\"setup\">Late Friday evening; a rest area on the second floor of Keyaki Mall; she stands in front of a lined-up vending machine; he stops by pretending to choose a product, tells her he hoped to find her there. He asks about an unnamed matter that does not involve Sakayanagi; she dodges a clear answer, then takes out her phone and plays a silent surveillance video dated December 26, 7 PM, Keyaki Mall — two people interacting closely, cautious of their surroundings; she gives the video of the one person matching his description.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"sakayanagi-arisu.html\">Sakayanagi Arisu<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “How have things been with Sakayanagi since then?”<span class=\"pg\">p.44<\/span><\/li><li class=\"q spoken\">“We’ve had more opportunities to talk than before.”<span class=\"pg\">p.44<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “I stopped by hoping you would be here, Yamamura. Actually, there’s something I want to ask.”<span class=\"pg\">p.44<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “The only person I found during my investigation that matches what you’re talking about is this person.”<span class=\"pg\">p.45<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I hope it helps.”<span class=\"pg\">p.45<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Nothing in the text names the two people in the video; the names are never printed on these pages. He uses the clip to summon Matsushita the next step.<span class=\"pg\">p.45<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> Member of Class A known for surveillance work; she gathers the information for Sakayanagi, per this volume&#x27;s later reveal.<span class=\"pg\">p.44–45<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-yamamura-miki-y2v12-p47-1\">→ After: Mentioned in passing<\/button><\/div><\/article>"},{"i":"sc-yamamura-miki-y2v12-p47-1","v":"y2v12","y":2,"o":31,"k":"","w":"yamamura-miki","q":"yamamura miki mentioned in passing named in passing    based on information i had obtained from yamamura    the video evidence anchoring everything he tells matsushita  named in passing    confidants like kamuro  hashimoto  and kito    her old trust circle named by sakayanagi  named in passing    this change began with kamuro and yamamura  significantly influenced by that recent incident  named in passing    maybe it s okay to win this special exam and bring hashimoto back into the fold  passing mention only  her scene entries are recorded separately in her own sections","h":"<article class=\"card\" id=\"sc-yamamura-miki-y2v12-p47-1\"><h3><span class=\"ttl\">Mentioned in passing<\/span><span class=\"meta\">Y2V12 · p.47, 59–60, 216<\/span><\/h3><p class=\"setup\">Named in passing — “based on information I had obtained from Yamamura” — the video evidence anchoring everything he tells Matsushita. Named in passing — “confidants like Kamuro, Hashimoto, and Kitō” — her old trust circle named by Sakayanagi. Named in passing — “This change began with Kamuro and Yamamura, significantly influenced by that recent incident.” Named in passing — “Maybe it&#x27;s okay to win this special exam and bring Hashimoto back into the fold.”<\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Mentioned<\/span> Passing mention only; her scene entries are recorded separately in her own sections.<span class=\"pg\">p.47, 59–60, 216<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-yamamura-miki-y2v12-p44-1\">← Before: Ch.2: The rest-area vending machines<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-yamamura-miki-y2v12-p106-1\">→ After: Ch.5: First-discussion participant list (A vs C, Sanada vs Katsuragi)<\/button><\/div><\/article>"},{"i":"sc-yamamura-miki-y2v12-p106-1","v":"y2v12","y":2,"o":31,"k":"","w":"yamamura-miki","q":"yamamura miki ch 5  first discussion participant list  a vs c  sanada vs katsuragi  named in the first discussion participant list for the katsuragi match   class a side  no dialogue or action is printed for her on these pages  the role is never disclosed","h":"<article class=\"card\" id=\"sc-yamamura-miki-y2v12-p106-1\"><h3><span class=\"ttl\">Ch.5: First-discussion participant list (A vs C, Sanada vs Katsuragi)<\/span><span class=\"meta\">Y2V12 · p.106<\/span><\/h3><p class=\"setup\">Named in the first-discussion participant list for the Katsuragi match — Class A side.<\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> No dialogue or action is printed for her on these pages; the role is never disclosed.<span class=\"pg\">p.106<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-yamamura-miki-y2v12-p47-1\">← Before: Mentioned in passing<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-yamamura-miki-y2v12-p210-1\">→ After: Epilogue: The investigator<\/button><\/div><\/article>"},{"i":"sc-yamamura-miki-y2v12-p210-1","v":"y2v12","y":2,"o":31,"k":"","w":"sakayanagi-arisu yamamura-miki","q":"yamamura miki epilogue  the investigator sakayanagi notes she had yamamura san investigate various things for a long time   for hashimoto s habit of hiding in the toilet when troubled   images of yamamura and her classmates flashed through her mind  maybe there was a future where she d fulfill her promise with kamuro  or join hands with hashimoto again  sakayanagi s surveillance of her own classmates for months  nothing came of it except her own paranoia  her eyes   the woman who watched everyone  trusted no one","h":"<article class=\"card\" id=\"sc-yamamura-miki-y2v12-p210-1\"><h3><span class=\"ttl\">Epilogue: The investigator<\/span><span class=\"meta\">Y2V12 · p.210, 214<\/span><\/h3><p class=\"setup\">Sakayanagi notes she had Yamamura-san investigate various things for a long time — for Hashimoto&#x27;s habit of hiding in the toilet when troubled. “Images of Yamamura and her classmates flashed through her mind. Maybe there was a future where she’d fulfill her promise with Kamuro, or join hands with Hashimoto again.”<\/p><p class=\"with\">with <a href=\"sakayanagi-arisu.html\">Sakayanagi Arisu<\/a><\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Caveat<\/span> Sakayanagi&#x27;s surveillance of her own classmates for months; nothing came of it except her own paranoia.<span class=\"pg\">p.210<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> Her eyes — the woman who watched everyone, trusted no one.<span class=\"pg\">p.210–214<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-yamamura-miki-y2v12-p106-1\">← Before: Ch.5: First-discussion participant list (A vs C, Sanada vs Katsuragi)<\/button><\/div><\/article>"},{"i":"sc-yamamura-miki-y2v12_5-p43-1","v":"y2v12.5","y":2,"o":32,"k":"spoken","w":"morishita-ai ayanokouji-kiyotaka sakayanagi-arisu yamamura-miki","q":"yamamura miki ch 3  waiting for morishita behind the dorm yamamura and morishita are late for the 10 a m  meeting  ayanokoji calls her at 8 something  she answers flustered  says they are behind the dorm  she apologizes for morishita s lateness and relays the meeting place  she attends despite her shyness and low self esteem  morishita is crouching observing insects  yamamura urges ayanokoji to be quiet  yamamura sighs that morishita has been observing for over 30 minutes   it s been over 30 minutes   uh  well  it s not that i doubt you  but more like  surprised   th that s too close i can t see anything  or rather  it s too bright   well  i might be a bit interested  actually   honestly  i still can t quite accept it   the class atmosphere has become incredibly heavy   well  i wouldn t go that far   aren t you going to blame the person who created this situation  sakayanagi  for acting selfishly   i don t know  maybe we have to give up on class a   students like me  well  i can t deny it   t the possibility is   am  am i really being talked about like that   that s expected  it would be a big problem if they were cheerful under these circumstances   u um   thin paper   eh  ehh  it doesn t feel like that at all   if possible   but  ichinose san s class has a similar amount of class points  but everyone is smiling  right  they seem positive  our situations aren t much different  isn t it   what do we do now   could it be  from now on  you will lead the class  morishita san   impossible  huh   u umm  morishita san  what traitor  she became friends with sakayanagi  who had merely used her at first  she still cannot accept the withdrawal","h":"<article class=\"card\" id=\"sc-yamamura-miki-y2v12_5-p43-1\"><h3><span class=\"ttl\">Ch.3: Waiting for Morishita behind the dorm<\/span><span class=\"meta\">Y2V12.5 · p.43–53<\/span><\/h3><p class=\"setup\">Yamamura and Morishita are late for the 10 a.m. meeting; Ayanokōji calls her at 8-something; she answers flustered, says they are behind the dorm. Morishita is crouching observing insects; Yamamura urges Ayanokōji to be quiet. Yamamura sighs that Morishita has been observing for over 30 minutes.<\/p><p class=\"with\">with <a href=\"morishita-ai.html\">Morishita Ai<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"sakayanagi-arisu.html\">Sakayanagi Arisu<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“It’s been over 30 minutes...”<span class=\"pg\">p.47<\/span><\/li><li class=\"q spoken\">“Uh, well, it’s not that I doubt you, but more like... surprised...”<span class=\"pg\">p.47<\/span><\/li><li class=\"q spoken\">“Th-that’s too close—I can’t see anything. Or rather, it’s too bright...!”<span class=\"pg\">p.47<\/span><\/li><\/ul><details class=\"more\"><summary>21 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Morishita Ai<\/b> She apologizes for Morishita&#x27;s lateness and relays the meeting place.<span class=\"pg\">p.43–53<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> She attends despite her shyness and low self-esteem.<span class=\"pg\">p.43–53<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well... I might be a bit interested, actually.”<span class=\"pg\">p.49<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “...Honestly, I still can’t quite accept it...”<span class=\"pg\">p.50<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “The class atmosphere has become incredibly heavy...”<span class=\"pg\">p.50<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Well, I wouldn’t go that far...”<span class=\"pg\">p.50<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Aren’t you going to blame the person who created this situation, Sakayanagi, for acting selfishly?”<span class=\"pg\">p.50<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don’t know... maybe we have to give up on Class A...”<span class=\"pg\">p.50<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Students like me... Well, I can’t deny it...”<span class=\"pg\">p.51<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “T-The possibility is?”<span class=\"pg\">p.51<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Am... am I really being talked about like that?”<span class=\"pg\">p.51<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That’s expected. It would be a big problem if they were cheerful under these circumstances.”<span class=\"pg\">p.52<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “U-Um. ‘Thin paper’...”<span class=\"pg\">p.52<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Eh, ehh...? It doesn’t feel like that at all...”<span class=\"pg\">p.52<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “If possible...”<span class=\"pg\">p.52<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “But... Ichinose-san’s class has a similar amount of class points, but everyone is smiling... right? They seem positive… Our situations aren’t much different, isn’t it?”<span class=\"pg\">p.52<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “What do we do now?”<span class=\"pg\">p.52<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Could it be... from now on, you will lead the class, Morishita-san...?”<span class=\"pg\">p.52<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Impossible, huh…?”<span class=\"pg\">p.52<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “U-Umm, Morishita-san, what traitor?”<span class=\"pg\">p.53<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> She became friends with Sakayanagi, who had merely used her at first; she still cannot accept the withdrawal.<span class=\"pg\">p.50–53<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-yamamura-miki-y2v12_5-p93-1\">→ After: Ch.6: Sakayanagi&#x27;s farewell and the advice<\/button><\/div><\/article>"},{"i":"sc-yamamura-miki-y2v12_5-p93-1","v":"y2v12.5","y":2,"o":32,"k":"spoken","w":"sakayanagi-arisu morishita-ai ayanokouji-kiyotaka yamamura-miki","q":"yamamura miki ch 6  sakayanagi s farewell and the advice yamamura is at the main gate to see sakayanagi off  standing beside morishita  she distances herself with the others when sakayanagi asks to speak to ayanokoji alone  sakayanagi exchanges renewed promises to reunite with her classmates  yamamura cries at last  wanting to spend another year together   why not  i want to know   that is  true   how we should fight  but  is that even allowed   let s do it  it s advice left by none other than sakayanagi san   i is it a love letter   i don t smell anything though   a phone number  it seems  she peers flustered into the envelope  eleven digits and the initial n  their class cannot tell who the sender is  she cries at the farewell  sakayanagi was her first true friend  morishita sees her off with her  clinging rather than grieving  he explains sakayanagi s  advice  for the former class a to her  she wants to give it a try","h":"<article class=\"card\" id=\"sc-yamamura-miki-y2v12_5-p93-1\"><h3><span class=\"ttl\">Ch.6: Sakayanagi&#x27;s farewell and the advice<\/span><span class=\"meta\">Y2V12.5 · p.93–106<\/span><\/h3><p class=\"setup\">Yamamura is at the main gate to see Sakayanagi off, standing beside Morishita; she distances herself with the others when Sakayanagi asks to speak to Ayanokōji alone. Sakayanagi exchanges renewed promises to reunite with her classmates; Yamamura cries at last, wanting to spend another year together.<\/p><p class=\"with\">with <a href=\"sakayanagi-arisu.html\">Sakayanagi Arisu<\/a> · <a href=\"morishita-ai.html\">Morishita Ai<\/a> · <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">“Why not? I want to know.”<span class=\"pg\">p.102<\/span><\/li><li class=\"q spoken\">“That is... true...”<span class=\"pg\">p.102<\/span><\/li><li class=\"q spoken\">“How we should fight... But, is that even allowed?”<span class=\"pg\">p.103<\/span><\/li><\/ul><details class=\"more\"><summary>8 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Let’s do it... It’s advice left by none other than Sakayanagi-san...”<span class=\"pg\">p.103<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I-Is it a love letter?”<span class=\"pg\">p.105<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I don’t smell anything though?”<span class=\"pg\">p.105<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “A phone number... it seems.”<span class=\"pg\">p.105<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> She peers flustered into the envelope; eleven digits and the initial N. Their class cannot tell who the sender is.<span class=\"pg\">p.105–106<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> She cries at the farewell; Sakayanagi was her first true friend.<span class=\"pg\">p.93–102<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Morishita Ai<\/b> Morishita sees her off with her, clinging rather than grieving.<span class=\"pg\">p.93–102<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> He explains Sakayanagi&#x27;s &quot;advice&quot; for the former Class A to her; she wants to give it a try.<span class=\"pg\">p.102–106<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-yamamura-miki-y2v12_5-p43-1\">← Before: Ch.3: Waiting for Morishita behind the dorm<\/button><\/div><\/article>"},{"i":"sc-yamamura-miki-y3v2-p152-1","v":"y3v2","y":3,"o":34,"k":"spoken","w":"ayanokouji-kiyotaka morishita-ai shiraishi-asuka yamamura-miki","q":"yamamura miki ch 5   depth read  yamamura s courage to change appears silently outside the south entrance after leading them on a change of meeting place   s sorry   y  yes  since you transferred classes  ayanokouji kun  we still  haven t said a single word to each other  so   i want to change  i want to have more self confidence  to be able to smile in front of others   please let me  help with getting to class a  too   i want to do more  much more  because i believe  there s something  that only i can do   yes  if you re okay with it  ayanokouji kun  i think i can  try to investigate shiraishi san in my own way  extremely shy and passive  but mustering real courage to voice her desire to change  ayanokoji sees it as evolution  not regression  confides her wish to change and accepts his task to investigate shiraishi  is startled by morishita s  ear gun   blowing in her ear  which oddly helps ease her tension  is asked to investigate her","h":"<article class=\"card\" id=\"sc-yamamura-miki-y3v2-p152-1\"><h3><span class=\"ttl\">Ch.5 — depth read: Yamamura&#x27;s courage to change<\/span><span class=\"meta\">Y3V2 · p.152–181<\/span><\/h3><p class=\"setup\">Appears silently outside the south entrance after leading them on a change of meeting place.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"morishita-ai.html\">Morishita Ai<\/a> · <a href=\"shiraishi-asuka.html\">Shiraishi Asuka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;S-Sorry.&quot;<span class=\"pg\">p.157<\/span><\/li><li class=\"q spoken\">&quot;Y... Yes. Since you transferred classes, Ayanokouji-kun, we still... haven&#x27;t said a single word to each other... so...&quot;<span class=\"pg\">p.157<\/span><\/li><li class=\"q spoken\">&quot;I want to change. I want to have more self-confidence, to be able to smile in front of others.&quot;<span class=\"pg\">p.161<\/span><\/li><\/ul><details class=\"more\"><summary>7 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;Please let me... help with getting to Class A, too.&quot;<span class=\"pg\">p.161<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I want to do more... much more. Because I believe... there&#x27;s something... that only I can do.&quot;<span class=\"pg\">p.161<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Yes... If you&#x27;re okay with it, Ayanokouji-kun, I think I can... try to investigate Shiraishi-san in my own way.&quot;<span class=\"pg\">p.162<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Extremely shy and passive, but mustering real courage to voice her desire to change; Ayanokōji sees it as evolution, not regression.<span class=\"pg\">p.157–161<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Confides her wish to change and accepts his task to investigate Shiraishi.<span class=\"pg\">p.157–163<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Morishita Ai<\/b> Is startled by Morishita&#x27;s &quot;Ear Gun&quot; (blowing in her ear), which oddly helps ease her tension.<span class=\"pg\">p.158–159<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Shiraishi Asuka<\/b> Is asked to investigate her.<span class=\"pg\">p.162<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-yamamura-miki-y3v2-p157-1\">→ After: Yamamura&#x27;s courage to change<\/button><\/div><\/article>"},{"i":"sc-yamamura-miki-y3v2-p157-1","v":"y3v2","y":3,"o":34,"k":"spoken","w":"ayanokouji-kiyotaka morishita-ai yamamura-miki","q":"yamamura miki yamamura s courage to change appears soundlessly at the south entrance after leading ayanokoji and morishita around  bows in apology   s sorry   y  yes  since you transferred classes  ayanokouji kun  we still  haven t said a single word to each other  so   um  i i  therefore   i want to change  i want to have more self confidence  to be able to smile in front of others   please let me  help with getting to class a  too   i want to do more  much more  because i believe  there s something  that only i can do  extremely shy and passive but mustering real courage   ayanokoji reads her fidgeting not as regression but as evolution  a sign of breaking from her past self  after morishita s  ear gun  relaxes her  she speaks more clearly and finally holds his gaze  confides her wish to change  accepts his task to investigate shiraishi despite having expected an external target  morishita blows in her ear  ear gun  startling her but easing her tension","h":"<article class=\"card\" id=\"sc-yamamura-miki-y3v2-p157-1\"><h3><span class=\"ttl\">Yamamura&#x27;s courage to change<\/span><span class=\"meta\">Y3V2 · p.157–161<\/span><\/h3><p class=\"setup\">Appears soundlessly at the south entrance after leading Ayanokōji and Morishita around; bows in apology.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"morishita-ai.html\">Morishita Ai<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;S-Sorry.&quot;<span class=\"pg\">p.157<\/span><\/li><li class=\"q spoken\">&quot;Y... Yes. Since you transferred classes, Ayanokouji-kun, we still... haven&#x27;t said a single word to each other... so...&quot;<span class=\"pg\">p.157<\/span><\/li><li class=\"q spoken\">&quot;Um... I-I, therefore...&quot;<span class=\"pg\">p.158<\/span><\/li><\/ul><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> &quot;I want to change. I want to have more self-confidence, to be able to smile in front of others.&quot;<span class=\"pg\">p.161<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;Please let me... help with getting to Class A, too.&quot;<span class=\"pg\">p.161<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> &quot;I want to do more... much more. Because I believe... there&#x27;s something... that only I can do.&quot;<span class=\"pg\">p.161<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Extremely shy and passive but mustering real courage — Ayanokōji reads her fidgeting not as regression but as evolution, a sign of breaking from her past self; after Morishita&#x27;s &quot;Ear Gun&quot; relaxes her, she speaks more clearly and finally holds his gaze.<span class=\"pg\">p.157–161<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Confides her wish to change; accepts his task to investigate Shiraishi despite having expected an external target.<span class=\"pg\">p.157–163<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Morishita Ai<\/b> Morishita blows in her ear (&quot;Ear Gun&quot;), startling her but easing her tension.<span class=\"pg\">p.158–159<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-yamamura-miki-y3v2-p152-1\">← Before: Ch.5 — depth read: Yamamura&#x27;s courage to change<\/button><\/div><\/article>"},{"i":"sc-yamamura-miki-y3v3-p86-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ayanokouji-kiyotaka yamamura-miki","q":"yamamura miki ch 3   depth read  yamamura s fear and reassurance  it s just  it s scary  isn t it  if i get separated  i won t have any idea where my allies are or where the enemy is  right  anxious about being separated and feeling useless after class c lost nishikawa  a vip  nods with resolve after ayanokoji s reassurance  is reassured by him that simply surviving is a contribution","h":"<article class=\"card\" id=\"sc-yamamura-miki-y3v3-p86-1\"><h3><span class=\"ttl\">Ch.3 — depth read: Yamamura&#x27;s fear and reassurance<\/span><span class=\"meta\">Y3V3 · p.86–118<\/span><\/h3><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;It&#x27;s just... it&#x27;s scary, isn&#x27;t it? If I get separated, I won&#x27;t have any idea where my allies are or where the enemy is, right?&quot;<span class=\"pg\">p.94<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Anxious about being separated and feeling useless after Class C lost Nishikawa (a VIP); nods with resolve after Ayanokōji&#x27;s reassurance.<span class=\"pg\">p.94<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Is reassured by him that simply surviving is a contribution.<span class=\"pg\">p.94<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-yamamura-miki-y3v3-p94-1\">→ After: Yamamura&#x27;s fear of being separated<\/button><\/div><\/article>"},{"i":"sc-yamamura-miki-y3v3-p94-1","v":"y3v3","y":3,"o":35,"k":"spoken","w":"ayanokouji-kiyotaka yamamura-miki","q":"yamamura miki yamamura s fear of being separated looks anxious as the class prepares to split into supply teams   it s just  it s scary  isn t it  if i get separated  i won t have any idea where my allies are or where the enemy is  right   and there s nothing i can do to be of use   is that  really all it takes  anxious about being separated and feeling useless after class c lost vip nishikawa  gives a small  definite nod after ayanokoji s reassurance  is reassured by him that simply surviving is a contribution","h":"<article class=\"card\" id=\"sc-yamamura-miki-y3v3-p94-1\"><h3><span class=\"ttl\">Yamamura&#x27;s fear of being separated<\/span><span class=\"meta\">Y3V3 · p.94<\/span><\/h3><p class=\"setup\">Looks anxious as the class prepares to split into supply teams.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\">&quot;It&#x27;s just... it&#x27;s scary, isn&#x27;t it? If I get separated, I won&#x27;t have any idea where my allies are or where the enemy is, right?&quot;<span class=\"pg\">p.94<\/span><\/li><li class=\"q spoken\">&quot;And there&#x27;s nothing I can do to be of use...&quot;<span class=\"pg\">p.94<\/span><\/li><li class=\"q spoken\">&quot;Is that... really all it takes?&quot;<span class=\"pg\">p.94<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Anxious about being separated and feeling useless after Class C lost VIP Nishikawa; gives a small, definite nod after Ayanokōji&#x27;s reassurance.<span class=\"pg\">p.94<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Is reassured by him that simply surviving is a contribution.<span class=\"pg\">p.94<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-yamamura-miki-y3v3-p86-1\">← Before: Ch.3 — depth read: Yamamura&#x27;s fear and reassurance<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-yamamura-miki-y3v3-p233-1\">→ After: Epilogue — depth read: the unseen final guard<\/button><\/div><\/article>"},{"i":"sc-yamamura-miki-y3v3-p233-1","v":"y3v3","y":3,"o":35,"k":"","w":"ayanokouji-kiyotaka ryuuen-kakeru yamamura-miki","q":"yamamura miki epilogue   depth read  the unseen final guard arrives out of breath with shiraishi  kanzaki and the two class d vips after ayanokoji s solo action  too exhausted to speak  survives to the final stage as class c s last guard and is named by ayanokoji as the ideal person to sneak up silently   light  nimble and skilled at erasing her presence   which makes the bluff against ryuen credible  is named as the guard who might be positioned behind ryuen  though she was never actually there  is used as a phantom threat to force him to turn around in the final standoff","h":"<article class=\"card\" id=\"sc-yamamura-miki-y3v3-p233-1\"><h3><span class=\"ttl\">Epilogue — depth read: the unseen final guard<\/span><span class=\"meta\">Y3V3 · p.233–252<\/span><\/h3><p class=\"setup\">Arrives out of breath with Shiraishi, Kanzaki and the two Class D VIPs after Ayanokōji&#x27;s solo action; too exhausted to speak.<\/p><p class=\"with\">with <a href=\"ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"ryuuen-kakeru.html\">Ryūen Kakeru<\/a><\/p><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Trait<\/span> Survives to the final stage as Class C&#x27;s last guard and is named by Ayanokōji as the ideal person to sneak up silently — light, nimble and skilled at erasing her presence — which makes the bluff against Ryūen credible.<span class=\"pg\">p.233, 246<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Is named as the guard who might be positioned behind Ryūen, though she was never actually there.<span class=\"pg\">p.246<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> Is used as a phantom threat to force him to turn around in the final standoff.<span class=\"pg\">p.246<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-yamamura-miki-y3v3-p94-1\">← Before: Yamamura&#x27;s fear of being separated<\/button><\/div><\/article>"}];
